//! Stationary permeable Ffowcs Williams--Hawkings surface formulation.
//!
//! For a fixed closed surface in a homogeneous quiescent medium, the linear
//! frequency-domain FW-H equation reduces to the Kirchhoff surface integral.
//! This implementation consumes the complex pressure and outward normal
//! velocity on quadrature patches and evaluates observers outside the surface.
//! Harmonic amplitudes use `exp(i omega t)` and `exp(-i k r)` propagation.
//!
//! The returned `thickness` term is generated by normal velocity; `loading` is
//! generated by surface pressure. Their sum reconstructs the exterior field.
//! Moving/deforming surfaces, uniform-flow convected Green functions, and the
//! exterior quadrupole term are deliberately outside this stationary model.
//!
//! # Reference
//!
//! J. E. Ffowcs Williams and D. L. Hawkings, "Sound Generation by Turbulence
//! and Surfaces in Arbitrary Motion", *Philosophical Transactions of the Royal
//! Society A* 264 (1969), 321--342.

use num_complex::Complex64;
use std::f64::consts::PI;

use super::error::{AeroacousticsError, require_finite, require_positive};

/// One quadrature patch on a closed permeable FW-H surface.
#[derive(Debug, Clone, Copy)]
pub struct FwhSurfacePatch {
    /// Patch centroid `[m]`.
    pub position: [f64; 3],
    /// Unit normal pointing from the enclosed source region to the observer region.
    pub outward_normal: [f64; 3],
    /// Patch quadrature area `[m^2]`.
    pub area: f64,
    /// Complex acoustic pressure on the surface `[Pa]`.
    pub pressure: Complex64,
    /// Complex outward particle velocity on the surface `[m/s]`.
    pub normal_velocity: Complex64,
}

impl FwhSurfacePatch {
    /// Construct and validate one permeable-surface quadrature patch.
    pub fn new(
        position: [f64; 3],
        outward_normal: [f64; 3],
        area: f64,
        pressure: Complex64,
        normal_velocity: Complex64,
    ) -> Result<Self, AeroacousticsError> {
        require_positive("surface patch area", area)?;
        if position.iter().any(|x| !x.is_finite()) {
            return Err(AeroacousticsError::NonFiniteField { name: "position" });
        }
        if outward_normal.iter().any(|x| !x.is_finite()) {
            return Err(AeroacousticsError::NonFiniteField {
                name: "outward_normal",
            });
        }
        let normal_norm = norm(outward_normal);
        if !normal_norm.is_finite() || (normal_norm - 1.0).abs() > 1e-8 {
            return Err(AeroacousticsError::NonFiniteField {
                name: "unit outward_normal",
            });
        }
        if !is_finite_complex(pressure) {
            return Err(AeroacousticsError::NonFiniteField { name: "pressure" });
        }
        if !is_finite_complex(normal_velocity) {
            return Err(AeroacousticsError::NonFiniteField {
                name: "normal_velocity",
            });
        }
        Ok(Self {
            position,
            outward_normal,
            area,
            pressure,
            normal_velocity,
        })
    }
}

/// Thickness, loading, and total complex FW-H pressure at an observer.
#[derive(Debug, Clone, Copy, Default)]
pub struct FwhComponents {
    /// Normal-velocity (thickness/monopole) contribution `[Pa]`.
    pub thickness: Complex64,
    /// Surface-pressure (loading/dipole) contribution `[Pa]`.
    pub loading: Complex64,
    /// `thickness + loading` `[Pa]`.
    pub total: Complex64,
}

/// Evaluate a stationary permeable FW-H surface at one exterior observer.
pub fn stationary_fwh_pressure(
    patches: &[FwhSurfacePatch],
    observer: [f64; 3],
    angular_frequency: f64,
    density: f64,
    speed_of_sound: f64,
) -> Result<FwhComponents, AeroacousticsError> {
    require_finite("angular_frequency", angular_frequency)?;
    require_positive("density", density)?;
    require_positive("speed_of_sound", speed_of_sound)?;
    if observer.iter().any(|x| !x.is_finite()) {
        return Err(AeroacousticsError::NonFiniteField { name: "observer" });
    }

    let wavenumber = angular_frequency / speed_of_sound;
    let mut thickness = Complex64::new(0.0, 0.0);
    let mut loading = Complex64::new(0.0, 0.0);
    for patch in patches {
        // Revalidate public fields because callers can construct the public POD
        // directly rather than through FwhSurfacePatch::new.
        validate_patch(patch)?;
        let displacement = std::array::from_fn(|i| observer[i] - patch.position[i]);
        let distance = norm(displacement);
        if distance <= f64::EPSILON {
            return Err(AeroacousticsError::SingularObserver);
        }
        let direction = displacement.map(|x| x / distance);
        let green = Complex64::from_polar(1.0 / (4.0 * PI * distance), -wavenumber * distance);

        // Source-normal derivative of G(x,y), with R = x-y:
        // dG/dn_y = G (ik + 1/R) (R_hat . n_y).
        let normal_projection = dot(direction, patch.outward_normal);
        let green_normal_derivative =
            green * Complex64::new(1.0 / distance, wavenumber) * normal_projection;

        // For exp(i omega t), dp/dn = -i omega rho u_n. The exterior
        // representation is p*dG/dn - G*dp/dn.
        thickness += Complex64::new(0.0, angular_frequency * density)
            * patch.normal_velocity
            * green
            * patch.area;
        loading += patch.pressure * green_normal_derivative * patch.area;
    }

    Ok(FwhComponents {
        thickness,
        loading,
        total: thickness + loading,
    })
}

fn validate_patch(patch: &FwhSurfacePatch) -> Result<(), AeroacousticsError> {
    require_positive("surface patch area", patch.area)?;
    if patch.position.iter().any(|x| !x.is_finite())
        || patch.outward_normal.iter().any(|x| !x.is_finite())
        || !is_finite_complex(patch.pressure)
        || !is_finite_complex(patch.normal_velocity)
    {
        return Err(AeroacousticsError::NonFiniteField {
            name: "FW-H surface patch",
        });
    }
    let normal_norm = norm(patch.outward_normal);
    if (normal_norm - 1.0).abs() > 1e-8 {
        return Err(AeroacousticsError::NonFiniteField {
            name: "unit outward_normal",
        });
    }
    Ok(())
}

fn is_finite_complex(value: Complex64) -> bool {
    value.re.is_finite() && value.im.is_finite()
}

fn dot(lhs: [f64; 3], rhs: [f64; 3]) -> f64 {
    lhs.iter().zip(rhs).map(|(a, b)| a * b).sum()
}

fn norm(vector: [f64; 3]) -> f64 {
    dot(vector, vector).sqrt()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn monopole_pressure(position: [f64; 3], wavenumber: f64) -> Complex64 {
        let radius = norm(position);
        Complex64::from_polar(1.0 / radius, -wavenumber * radius)
    }

    fn monopole_sphere(
        radius: f64,
        n_mu: usize,
        n_phi: usize,
        omega: f64,
        density: f64,
        sound_speed: f64,
    ) -> Vec<FwhSurfacePatch> {
        let k = omega / sound_speed;
        let area = 4.0 * PI * radius * radius / (n_mu * n_phi) as f64;
        let mut patches = Vec::with_capacity(n_mu * n_phi);
        for m in 0..n_mu {
            let mu = -1.0 + 2.0 * (m as f64 + 0.5) / n_mu as f64;
            let radial = (1.0 - mu * mu).sqrt();
            for p in 0..n_phi {
                let phi = 2.0 * PI * (p as f64 + 0.5) / n_phi as f64;
                let normal = [radial * phi.cos(), radial * phi.sin(), mu];
                let position = normal.map(|x| radius * x);
                let pressure = monopole_pressure(position, k);
                let normal_gradient = pressure * Complex64::new(-1.0 / radius, -k);
                let normal_velocity =
                    Complex64::new(0.0, 1.0) * normal_gradient / (omega * density);
                patches.push(
                    FwhSurfacePatch::new(position, normal, area, pressure, normal_velocity)
                        .unwrap(),
                );
            }
        }
        patches
    }

    #[test]
    fn closed_surface_reconstructs_monopole() {
        let (omega, rho, c) = (2.0, 1.2, 3.0);
        let surface = monopole_sphere(0.5, 48, 96, omega, rho, c);
        let observer = [2.0, 0.3, -0.1];
        let actual = stationary_fwh_pressure(&surface, observer, omega, rho, c)
            .unwrap()
            .total;
        let expected = monopole_pressure(observer, omega / c);
        assert!((actual - expected).norm() / expected.norm() < 2e-3);
    }

    #[test]
    fn thickness_and_loading_sum_to_total() {
        let (omega, rho, c) = (4.0, 1.2, 3.0);
        let surface = monopole_sphere(0.7, 16, 32, omega, rho, c);
        let result = stationary_fwh_pressure(&surface, [3.0, 0.0, 0.0], omega, rho, c).unwrap();
        assert_eq!(result.total, result.thickness + result.loading);
        assert!(result.thickness.norm() > 0.0);
        assert!(result.loading.norm() > 0.0);
    }

    #[test]
    fn rejects_non_unit_surface_normal() {
        let patch = FwhSurfacePatch {
            position: [1.0, 0.0, 0.0],
            outward_normal: [2.0, 0.0, 0.0],
            area: 1.0,
            pressure: Complex64::new(1.0, 0.0),
            normal_velocity: Complex64::new(0.0, 0.0),
        };
        assert!(stationary_fwh_pressure(&[patch], [2.0, 0.0, 0.0], 1.0, 1.0, 1.0).is_err());
    }
}
